289	// metadataRevision is one immutable metadata revision of an object. Each
290	// object's revisions are kept in commit order, so the revision number of
291	// entry i is i+1. Metadata lives in process memory only: it creates no pin,
292	// takes no part in storage statistics, bundles or the audit log, and is
293	// deleted atomically with its object by garbage collection.
294	type metadataRevision struct {
295		revision    int64
296		contentType *string
