298		updatedAt   time.Time
299	}
300	
301	// commitMetadata appends one metadata revision for cid when expected equals
302	// the current revision number (0 before the first write). The check and the
303	// append happen under the write lock, so exactly one of several concurrent
304	// writers carrying the same expected revision commits. The returned string
305	// is empty on success or the error code to report: object_not_found or
306	// revision_conflict. created is true for the first revision of an object.
307	func (s *store) commitMetadata(cid string, expected int64, contentType *string, labels map[string]string, now time.Time) (rev metadataRevision, created bool, code string) {
308		s.mu.Lock()
309		defer s.mu.Unlock()
310		if _, ok := s.objects[cid]; !ok {
311			return metadataRevision{}, false, "object_not_found"
312		}
313		history := s.metadata[cid]
314		if int64(len(history)) != expected {
315			return metadataRevision{}, false, "revision_conflict"
316		}
317		rev = metadataRevision{
318			revision:    expected + 1,
319			contentType: contentType,
320			labels:      labels,
321			updatedAt:   now.UTC(),
322		}
323		s.metadata[cid] = append(history, rev)
324		return rev, expected == 0, ""
325	}
326	
327	// metadataAt returns the current metadata revision for cid, or the requested
328	// historical revision when revision > 0. The returned string is empty on
329	// success or the error code to report: object_not_found, metadata_not_found
330	// or metadata_revision_not_found.
331	func (s *store) metadataAt(cid string, revision int64) (metadataRevision, string) {
332		s.mu.RLock()
333		defer s.mu.RUnlock()
334		if _, ok := s.objects[cid]; !ok {
335			return metadataRevision{}, "object_not_found"
336		}
337		history := s.metadata[cid]
338		if len(history) == 0 {
339			return metadataRevision{}, "metadata_not_found"
340		}
341		if revision == 0 {
342			return history[len(history)-1], ""
343		}
344		if revision > int64(len(history)) {
345			return metadataRevision{}, "metadata_revision_not_found"
346		}
347		return history[revision-1], ""
348	}
349	
350	// refRevision is one immutable revision of a named reference. A ref points
351	// at an object by cid but creates no pin: the target may be garbage
352	// collected while the ref history stays readable. Revisions live in
353	// process memory only, take no part in storage statistics, bundles or the
354	// audit log, and are not deleted when the target object is collected.
355	type refRevision struct {
356		revision  int64
357		cid       string
358		updatedAt time.Time
359	}
360	
361	// commitRef appends one revision for name when expected equals the current
362	// revision number (0 before the first write) and cid names a live object.
363	// The existence check, revision check and append happen under one write
364	// lock, so exactly one of several concurrent writers carrying the same
365	// expected revision commits. The returned string is empty on success or the
366	// error code to report: object_not_found or revision_conflict. created is
367	// true for the first revision of a name. A new revision is recorded even
368	// when the cid is unchanged.
369	func (s *store) commitRef(name, cid string, expected int64, now time.Time) (rev refRevision, created bool, code string) {
370		s.mu.Lock()
371		defer s.mu.Unlock()
372		if _, ok := s.objects[cid]; !ok {
373			return refRevision{}, false, "object_not_found"
374		}
375		history := s.refs[name]
376		if int64(len(history)) != expected {
377			return refRevision{}, false, "revision_conflict"
378		}
379		rev = refRevision{revision: expected + 1, cid: cid, updatedAt: now.UTC()}
380		s.refs[name] = append(history, rev)
381		return rev, expected == 0, ""
382	}
383	
384	// refAt returns the current ref revision for name, or the requested
385	// historical revision when revision > 0. The returned string is empty on
386	// success or the error code to report: ref_not_found or
387	// ref_revision_not_found. Ref metadata stays readable after the target
388	// object has been garbage collected.
389	func (s *store) refAt(name string, revision int64) (refRevision, string) {
390		s.mu.RLock()
391		defer s.mu.RUnlock()
392		history := s.refs[name]
393		if len(history) == 0 {
394			return refRevision{}, "ref_not_found"
395		}
396		if revision == 0 {
397			return history[len(history)-1], ""
398		}
399		if revision > int64(len(history)) {
400			return refRevision{}, "ref_revision_not_found"
401		}
402		return history[revision-1], ""
403	}
404	
405	// resolveRefObject resolves a ref revision and its target object against a
406	// single consistent snapshot of the store: the read lock is held across
407	// both the history lookup and the object lookup, so resolution and object
408	// reading observe the same instant. It returns the resolved revision (also
409	// when the object is gone) and the error code to report: ref_not_found,
410	// ref_revision_not_found or reference_target_missing.
411	func (s *store) resolveRefObject(name string, revision int64) (rev refRevision, obj *object, code string) {
412		s.mu.RLock()
413		defer s.mu.RUnlock()
414		history := s.refs[name]
415		if len(history) == 0 {
416			return refRevision{}, nil, "ref_not_found"
417		}
418		if revision != 0 && revision > int64(len(history)) {
419			return refRevision{}, nil, "ref_revision_not_found"
420		}
421		if revision == 0 {
422			rev = history[len(history)-1]
423		} else {
424			rev = history[revision-1]
425		}
426		obj = s.objects[rev.cid]
427		if obj == nil {
428			return rev, nil, "reference_target_missing"
429		}
430		return rev, obj, ""
431	}
432	
433	// validCID reports whether s has the "sha256:<64 lowercase hex>" shape.
434	func validCID(s string) bool {
435		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
436			return false
437		}
438		for _, c := range s[len(cidPrefix):] {
439			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
440				return false
441			}
442		}
443		return true
