1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"net/http"
7		"strings"
8		"unicode/utf8"
9	)
10	
11	// gatewayPrefix anchors every read-only gateway route. The gateway is
12	// dispatched on the raw request target before ServeMux path cleaning, since
13	// the mux would rewrite or redirect raw ".", ".." and empty segments and its
14	// PathValue results are already percent-decoded, which would lose the exact
15	// single-decoding semantics the gateway contract requires.
16	const gatewayPrefix = "/v1/gateway/"
17	
18	// directoryMediaType is the media type of directory documents both when
19	// they are stored (as ordinary octet-stream objects) and when the gateway
20	// serves one back.
21	const directoryMediaType = "application/vnd.cidvault.directory+json"
22	
23	// directoryVersion is the only directory format version this server
24	// understands.
25	const directoryVersion = 1
26	
27	// maxDirectoryEntries bounds the number of entries one directory object may
28	// carry.
29	const maxDirectoryEntries = 4096
30	
31	// maxGatewaySegments bounds the number of path segments resolved in one
