187	// strictly increasing by Unicode code point, each name is one path segment
188	// of 1..255 code points without "/", "\\", "."/"..", NUL or other control
189	// characters, type is file or directory, and cid has the existing shape.
190	func parseDirectory(body []byte) (map[string]directoryEntry, bool) {
191		if !utf8.Valid(body) || !wellFormedJSON(body) {
192			return nil, false
193		}
