316		target := r.RequestURI
317		if target == "" {
318			target = r.URL.EscapedPath()
319		}
320		if i := strings.IndexByte(target, '?'); i >= 0 {
321			target = target[:i]
322		}
323		if !strings.HasPrefix(target, gatewayPrefix) {
324			return "", false
325		}
326		return target[len(gatewayPrefix):], true
327	}
