154	// empty or a single JSON object carrying only expiresAt, with no duplicate
155	// keys and no trailing data. The returned string is empty on success or the
156	// error code to report.
157	func decodeRecursivePinRequest(body []byte) (recursivePinRequest, string) {
158		var req recursivePinRequest
159		trimmed := bytes.TrimSpace(body)
160		if len(trimmed) == 0 {
161			return req, ""
162		}
163		dec := json.NewDecoder(bytes.NewReader(trimmed))
164		tok, err := dec.Token()
165		if err != nil {
166			return req, "invalid_request"
167		}
168		delim, ok := tok.(json.Delim)
169		if !ok || delim != '{' {
170			return req, "invalid_request"
171		}
172		seen := map[string]bool{}
173		for dec.More() {
174			keyTok, err := dec.Token()
175			if err != nil {
176				return req, "invalid_request"
177			}
178			key, ok := keyTok.(string)
179			if !ok || key != "expiresAt" || seen[key] {
180				return req, "invalid_request"
181			}
