202	// setRecursivePin validates the directory tree rooted at cid and commits the
203	// recursive pin atomically: the traversal, the existence checks and the
204	// commit all observe the same instant, so a garbage collection can neither
205	// interleave with the walk nor remove an object the new pin protects. A
206	// failed walk leaves no record behind. The returned string is empty on
207	// success or the error code to report with the given status:
208	// object_not_found, invalid_directory, recursive_pin_target_missing or
209	// recursive_pin_too_large. created is true when no valid recursive pin was
210	// in force for cid at now.
211	func (s *store) setRecursivePin(cid string, expiresAt *time.Time, now time.Time) (committed recursivePin, created bool, code string, status int) {
212		s.mu.Lock()
213		defer s.mu.Unlock()
214	
215		root, exists := s.objects[cid]
216		if !exists {
217			return recursivePin{}, false, "object_not_found", http.StatusNotFound
218		}
219		rootEntries, valid := parseDirectory(root.body())
220		if !valid {
221			return recursivePin{}, false, "invalid_directory", http.StatusUnprocessableEntity
222		}
223	
224		// Breadth-first walk over the directory tree. Members are de-duplicated
225		// by cid at enqueue time, so shared subtrees and reference cycles are
226		// visited once and each node is reached at its shallowest depth.
227		members := []string{cid}
228		totalBytes := root.size
229		visited := map[string]bool{cid: true}
230		queue := []walkChild{}
231		enqueue := func(entries map[string]directoryEntry, depth int) {
232			for _, c := range sortedDirectoryChildren(entries, depth) {
233				if !visited[c.cid] {
234					visited[c.cid] = true
235					queue = append(queue, c)
236				}
237			}
238		}
239		enqueue(rootEntries, 1)
240		for len(queue) > 0 {
241			node := queue[0]
242			queue = queue[1:]
243			if node.depth > maxRecursivePinDepth {
244				return recursivePin{}, false, "recursive_pin_too_large", http.StatusUnprocessableEntity
245			}
246			obj := s.objects[node.cid]
247			if obj == nil {
248				return recursivePin{}, false, "recursive_pin_target_missing", http.StatusFailedDependency
249			}
250			members = append(members, node.cid)
251			if len(members) > maxRecursivePinMembers {
252				return recursivePin{}, false, "recursive_pin_too_large", http.StatusUnprocessableEntity
253			}
254			totalBytes += obj.size
255			if !node.isDir {
256				continue
257			}
258			entries, valid := parseDirectory(obj.body())
259			if !valid {
260				return recursivePin{}, false, "invalid_directory", http.StatusUnprocessableEntity
261			}
262			enqueue(entries, node.depth+1)
263		}
264	
265		sort.Strings(members)
266		existing, found := s.recursivePins[cid]
267		created = !found || !validPin(pin{expiresAt: existing.expiresAt}, now)
268		s.recursivePins[cid] = recursivePin{expiresAt: expiresAt, members: members, bytes: totalBytes}
269		return s.recursivePins[cid], created, "", 0
270	}
271	
272	// walkChild is one enqueued directory-tree node awaiting its visit.
273	type walkChild struct {
274		cid   string
275		depth int
276		isDir bool
277	}
278	
279	// sortedDirectoryChildren flattens directory entries into a slice ordered by
280	// entry name, so the traversal order is deterministic.
281	func sortedDirectoryChildren(entries map[string]directoryEntry, depth int) []walkChild {
282		names := make([]string, 0, len(entries))
283		for name := range entries {
284			names = append(names, name)
285		}
286		sort.Strings(names)
287		children := make([]walkChild, 0, len(names))
288		for _, name := range names {
289			e := entries[name]
290			children = append(children, walkChild{cid: e.cid, depth: depth, isDir: e.typ == "directory"})
291		}
292		return children
293	}
294	
295	// recursivePinAt returns the recursive pin in force for cid at now,
296	// reporting whether one was found. Expired records are treated as absent.
297	func (s *store) recursivePinAt(cid string, now time.Time) (recursivePin, bool) {
298		s.mu.RLock()
299		defer s.mu.RUnlock()
300		p, found := s.recursivePins[cid]
301		if !found || !validPin(pin{expiresAt: p.expiresAt}, now) {
302			return recursivePin{}, false
303		}
304		return p, true
305	}
306	
307	// removeRecursivePin deletes the recursive pin for cid, reporting whether a
308	// valid one was in force at now. Expired records are removed lazily and
309	// reported as absent. The member objects are never touched and no audit
310	// event is recorded.
311	func (s *store) removeRecursivePin(cid string, now time.Time) bool {
312		s.mu.Lock()
313		defer s.mu.Unlock()
314		p, found := s.recursivePins[cid]
315		if !found || !validPin(pin{expiresAt: p.expiresAt}, now) {
316			delete(s.recursivePins, cid)
317			return false
318		}
319		delete(s.recursivePins, cid)
320		return true
321	}
